-- V15: Remove shipped demo seed data while preserving the tenant scaffold.
-- This keeps the demo tenant row available for fresh authoring but removes the
-- stock rules, patterns, SOPs, and example server inventory bundled by V2/V7/V8.

-- Seeded SOP ids from V2, V7, and V8.
DELETE FROM confidence_logs
WHERE sop_id IN (
    '20000000-0000-0000-0000-000000000001'::uuid,
